const minimumQuestions={qa:100,playwright:109,engineering:146,ai:104,ops:100};
function addExpandedQuestions(route, topics){let cursor=0;while(questions.filter(item=>item.r===route).length<minimumQuestions[route]){const topic=topics[cursor%topics.length],pattern=approaches[Math.floor(cursor/topics.length)%approaches.length];add(route,`${pattern[0]} ${topic}?`,pattern[1],`${pattern[2]} In this case, apply the principle directly to ${topic} and explain the trade-offs during the interview.`);cursor++;}}
Object.entries(expansionTopics).forEach(([route,topics])=>addExpandedQuestions(route,topics));
document.querySelector('.hero-actions').insertAdjacentHTML('beforeend','<a class="secondary" href="learning-guide.html">Open complete learning guide</a>');let active=[],index=0,score=0,answered=false,currentRoute='',selectedTag='all';const panel=document.querySelector('#questionPanel');const grid=document.querySelector('#routeGrid');const tagFilter=document.querySelector('#tagFilter');const questionCount=document.querySelector('#questionCount');
routes.forEach(r=>{const el=document.createElement('article');el.className='route';el.style.setProperty('--route',r.color);el.innerHTML=`<span class="route-num">${r.n} / MODULE</span><span class="route-icon">${r.icon}</span><h3>${r.title}</h3><p>${r.desc}</p><button>START PATH →</button>`;el.onclick=()=>start(r.id);grid.append(el)});
const totalQuestionCount=questions.length;document.querySelector('.metrics strong').textContent=totalQuestionCount;const availableTags=[...new Set(questions.flatMap(q=>q.tags))].sort();availableTags.forEach(tag=>tagFilter.add(new Option(tag,tag)));tagFilter.onchange=()=>{selectedTag=tagFilter.value};document.querySelector('#startFiltered').onclick=()=>start('all');
document.querySelector('#startAll').onclick=()=>{tagFilter.value='all';selectedTag='all';start('all')};document.querySelector('#restart').onclick=()=>start(currentRoute);
function shuffle(items){for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}return items}
function start(route){currentRoute=route;const requested=Number(questionCount.value);active=shuffle(questions.filter(x=>(route==='all'||x.r===route)&&(selectedTag==='all'||x.tags.includes(selectedTag)))).slice(0,requested);index=0;score=0;document.querySelector('#restart').hidden=false;document.querySelector('#quizTitle').textContent=route==='all'?'All modules':routes.find(x=>x.id===route).title;document.querySelector('#quizHint').textContent=`${active.length} of ${requested} requested questions selected${selectedTag==='all'?'':` for ${selectedTag}`}.`;document.querySelector('#simulator').scrollIntoView({behavior:'smooth',block:'center'});if(!active.length){panel.innerHTML='<div class="empty-state"><h3>No matching questions</h3><p>Choose a different tag or start all questions.</p></div>';updateProgress();return}render()}
function render(){answered=false;const q=active[index],letter=['A','B','C','D'];panel.innerHTML=`<div class="question"><div class="question-top">QUESTION ${index+1} OF ${active.length} · ${routes.find(x=>x.id===q.r).title.toUpperCase()}</div><h3>${q.q}</h3><div class="question-tags">${q.tags.map(tag=>`<span>${tag}</span>`).join('')}</div><div class="options">${q.a.map((x,i)=>`<button class="option" data-i="${i}"><strong>${letter[i]}</strong>${x}</button>`).join('')}</div><div id="feedback"></div></div>`;panel.querySelectorAll('.option').forEach(b=>b.onclick=()=>answer(+b.dataset.i));updateProgress()}
function answer(choice){if(answered)return;answered=true;const q=active[index],opts=panel.querySelectorAll('.option');opts.forEach((b,i)=>{b.disabled=true;if(i===q.c)b.classList.add('correct');if(i===choice&&i!==q.c)b.classList.add('wrong')});if(choice===q.c)score+=100;const good=choice===q.c;document.querySelector('#feedback').innerHTML=`<div class="explanation"><b>${good?'CORRECT ANSWER':'REVIEW THIS CONCEPT'}</b><p>${q.e}</p></div><button class="primary next" id="next">${index===active.length-1?'See result':'Next question →'}</button>`;document.querySelector('#next').onclick=next;updateProgress()}
function next(){index++;if(index>=active.length){panel.innerHTML=`<div class="empty-state"><div class="terminal-icon">OK</div><h3>Session completed</h3><p>You scored <b>${score}</b> out of ${active.length*100}. Repeat the path to reinforce the concepts or choose a new module.</p><button class="primary" onclick="start(currentRoute)">Repeat simulation</button></div>`;index=active.length;updateProgress();return}render()}
function updateProgress(){const total=active.length||1,pct=(index+(answered?1:0))/total*100;document.querySelector('#progressBar').style.width=pct+'%';document.querySelector('#progressText').textContent=active.length?`${Math.min(index+1,total)} / ${total} QUESTIONS`:'READY TO START';document.querySelector('#scoreText').textContent=score+' PTS'}
